<script lang="ts">
	import { onMount } from 'svelte';
	import SpecialAttributesDialog from '$lib/SpecialAttributesDialog.svelte';
	import { endEpisode, getEpisode, getEpisodeReadiness, episodeStateLabel, gridLabel, startEpisode, type Episode } from '$lib/episodes-api';
	import { logout } from '$lib/auth';
	import type { PageProps } from './$types';

	let { params }: PageProps = $props();
	let episode = $state<Episode | null>(null);
	let errorMessage = $state('');
	let isLoading = $state(true);
	let isManagingAttributes = $state(false);
	let readiness = $state<{ grid_locked: boolean; missing_roles: string[]; can_start: boolean } | null>(null);
	let isChangingState = $state(false);
	let stateError = $state('');

	const roleLabels: Record<string, string> = { PLAYER: 'un joueur', PRESENTER: 'un animateur', OPERATOR: 'un opérateur' };

	onMount(async () => {
		try {
			const [loadedEpisode, loadedReadiness] = await Promise.all([getEpisode(params.id), getEpisodeReadiness(params.id)]);
			episode = loadedEpisode;
			readiness = loadedReadiness;
		} catch (error) {
			errorMessage = error instanceof Error ? error.message : 'Impossible de charger cet épisode.';
		} finally {
			isLoading = false;
		}
	});

	async function toggleEpisodeState() {
		if (!episode || isChangingState) return;
		isChangingState = true;
		stateError = '';
		try {
			episode = episode.state === 'start' ? await endEpisode(episode.id) : await startEpisode(episode.id);
			readiness = await getEpisodeReadiness(episode.id);
		} catch (error) {
			stateError = error instanceof Error ? error.message : 'Impossible de modifier l’état de l’épisode.';
		} finally {
			isChangingState = false;
		}
	}

</script>

<svelte:head><title>{episode ? `${episode.title} · EpicQuiz - La Grille` : 'Épisode · EpicQuiz - La Grille'}</title></svelte:head>

<main id="content">
	<div class="page-actions"><a href="/">← Tous les épisodes</a><button type="button" onclick={logout}>Déconnexion</button></div>
	{#if isLoading}
		<p class="loading" role="status">Chargement de l’espace de gestion…</p>
	{:else if errorMessage}
		<section class="message" role="alert"><h1>Impossible d’ouvrir l’épisode</h1><p>{errorMessage}</p><a href="/">Retour aux épisodes</a></section>
	{:else if episode}
		<div class="workspace">
			<section class="board" aria-labelledby="episode-title">
				<header class="board-header"><div><p class="eyebrow">Épisode en préparation</p><h1 id="episode-title">{episode.title}</h1><p>Base du chronomètre : {episode.time_slot} s × niveau · {gridLabel(episode)}</p></div><div class="episode-actions"><span class="state {episode.state}"><i></i>{episodeStateLabel(episode.state)}</span><button class:stop={episode.state === 'start'} type="button" disabled={isChangingState || episode.state === 'end' || (episode.state === 'pending' && !readiness?.can_start)} onclick={() => void toggleEpisodeState()}>{isChangingState ? 'Mise à jour…' : episode.state === 'start' ? 'Arrêter l’épisode' : episode.state === 'end' ? 'Épisode terminé' : 'Lancer l’épisode'}</button></div></header>

				<section class="ready-panel" aria-labelledby="ready-title"><div><p class="eyebrow">Prochaine étape</p><h2 id="ready-title">Composez votre session</h2><p>Ajoutez les questions, construisez la grille puis invitez les personnes qui participeront à l’émission.</p></div><span>{gridLabel(episode)}</span></section>
				<section class="session-control" aria-labelledby="session-control-title"><div><p class="eyebrow">Contrôle de session</p><h2 id="session-control-title">{episode.state === 'start' ? 'Épisode en direct' : episode.state === 'end' ? 'Épisode terminé' : 'Prêt à lancer ?'}</h2>{#if episode.state === 'pending' && readiness}{#if readiness.can_start}<p>La grille est verrouillée et les rôles indispensables sont présents.</p>{:else if !readiness.grid_locked && readiness.missing_roles.length}<p>Verrouillez la grille et ajoutez {readiness.missing_roles.map((role) => roleLabels[role]).join(', ')}.</p>{:else if !readiness.grid_locked}<p>Verrouillez la grille.</p>{:else}<p>Ajoutez {readiness.missing_roles.map((role) => roleLabels[role]).join(', ')}.</p>{/if}{:else if episode.state === 'start'}<p>La session est en cours. Arrêtez-la lorsque la partie est terminée.</p>{:else}<p>Cette session est terminée et ne peut plus être relancée.</p>{/if}</div></section>
				{#if stateError}<p class="state-error" role="alert">{stateError}</p>{/if}

				<section class="manager-grid" aria-label="Étapes de préparation">
					<a id="questions" class="manager-card" href={`/episodes/${episode.id}/questions`}><span class="card-number">01</span><strong>Questions</strong><p>Composer et valider le questionnaire de cette session.</p><b>Gérer les questions <span aria-hidden="true">→</span></b></a>
					<button class="manager-card" type="button" onclick={() => isManagingAttributes = true}><span class="card-number">02</span><strong>Attributs spéciaux</strong><p>Préparer les lots et les vols disponibles pendant cette session.</p><b>Configurer les attributs <span aria-hidden="true">→</span></b></button>
					<a id="grid" class="manager-card featured" href={`/episodes/${episode.id}/grid`}><span class="card-number">03</span><strong>Grille</strong><p>Préparer les cases, les points et le tirage des attributs spéciaux.</p><b>Configurer la grille <span aria-hidden="true">→</span></b></a>
					<a id="participants" class="manager-card" href={`/episodes/${episode.id}/participants`}><span class="card-number">04</span><strong>Participants</strong><p>Inviter les joueurs, l’écran et les opérateurs.</p><b>Gérer les participants <span aria-hidden="true">→</span></b></a>
				</section>
			</section>

		</div>
		{#if isManagingAttributes}<SpecialAttributesDialog episodeId={episode.id} onclose={() => isManagingAttributes = false} onchange={() => undefined} />{/if}
	{/if}
</main>

<style>
